window.ScripturaLexicons.BDAG_PART_0224 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-01\" data-source=\"BDAG\" data-search=\"μαίνομαι verbo estar fora de si; enlouquecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαίνομαι</td><td>verbo</td><td>estar fora de si; enlouquecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-02\" data-source=\"BDAG\" data-search=\"μακαρίζω verbo considerar bem-aventurado; felicitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακαρίζω</td><td>verbo</td><td>considerar bem-aventurado; felicitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-03\" data-source=\"BDAG\" data-search=\"μακάριος, ία, ιον adjetivo bem-aventurado; feliz; afortunado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακάριος, ία, ιον</td><td>adjetivo</td><td>bem-aventurado; feliz; afortunado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-04\" data-source=\"BDAG\" data-search=\"μακαρισμός, οῦ, ὁ substantivo masculino declaração de bem-aventurança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακαρισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>declaração de bem-aventurança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-05\" data-source=\"BDAG\" data-search=\"Μακεδονία, ας, ἡ nome próprio feminino Macedônia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μακεδονία, ας, ἡ</td><td>nome próprio feminino</td><td>Macedônia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-06\" data-source=\"BDAG\" data-search=\"Μακεδών, όνος, ὁ substantivo masculino macedônio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μακεδών, όνος, ὁ</td><td>substantivo masculino</td><td>macedônio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-07\" data-source=\"BDAG\" data-search=\"μάκελλον, ου, τό substantivo neutro mercado de carne; mercado de alimentos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάκελλον, ου, τό</td><td>substantivo neutro</td><td>mercado de carne; mercado de alimentos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-08\" data-source=\"BDAG\" data-search=\"μακράν advérbio e preposição longe; distante; em tempo futuro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακράν</td><td>advérbio e preposição</td><td>longe; distante; em tempo futuro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-09\" data-source=\"BDAG\" data-search=\"μακρόβιος, ον adjetivo longevo; de vida longa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακρόβιος, ον</td><td>adjetivo</td><td>longevo; de vida longa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-10\" data-source=\"BDAG\" data-search=\"μακρόθεν advérbio de longe; a distância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακρόθεν</td><td>advérbio</td><td>de longe; a distância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-11\" data-source=\"BDAG\" data-search=\"μακροθυμέω verbo ter paciência; suportar; demorar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακροθυμέω</td><td>verbo</td><td>ter paciência; suportar; demorar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-12\" data-source=\"BDAG\" data-search=\"μακροθυμία, ας, ἡ substantivo feminino paciência; longanimidade; perseverança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακροθυμία, ας, ἡ</td><td>substantivo feminino</td><td>paciência; longanimidade; perseverança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-13\" data-source=\"BDAG\" data-search=\"μακρόθυμος, ον adjetivo paciente; longânimo; tolerante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακρόθυμος, ον</td><td>adjetivo</td><td>paciente; longânimo; tolerante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-14\" data-source=\"BDAG\" data-search=\"μακροθύμως advérbio pacientemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακροθύμως</td><td>advérbio</td><td>pacientemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-15\" data-source=\"BDAG\" data-search=\"μακρός, ά, όν adjetivo longo; distante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακρός, ά, όν</td><td>adjetivo</td><td>longo; distante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-16\" data-source=\"BDAG\" data-search=\"μακροχρόνιος, ον adjetivo longevo; de longa vida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μακροχρόνιος, ον</td><td>adjetivo</td><td>longevo; de longa vida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-17\" data-source=\"BDAG\" data-search=\"μάλα advérbio muito; extremamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάλα</td><td>advérbio</td><td>muito; extremamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-18\" data-source=\"BDAG\" data-search=\"μαλακία, ας, ἡ substantivo feminino debilidade; fraqueza; enfermidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαλακία, ας, ἡ</td><td>substantivo feminino</td><td>debilidade; fraqueza; enfermidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-19\" data-source=\"BDAG\" data-search=\"μαλακίζομαι verbo médio-passivo enfraquecer; adoecer; desanimar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαλακίζομαι</td><td>verbo médio-passivo</td><td>enfraquecer; adoecer; desanimar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0224-20\" data-source=\"BDAG\" data-search=\"μαλακός, ή, όν adjetivo macio; efeminado (sentido contextual) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαλακός, ή, όν</td><td>adjetivo</td><td>macio; efeminado (sentido contextual)</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0224-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαίνομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαίνομαι</span> (Hom. e outros; POxy 33 IV, 9ss.; PHerm 7 I, 18; LXX; TestJob; TestJos 8:3; ParJer 5:20; SibOr 4, 83; Philo; Jos., Bell. 1, 352, C. Ap. 1, 204; apolog. exc. Mel.) estar louco, estar fora de si; em associação com <span class=\"greek\">δαιμόνιον</span> <span class=\"greek\">ἔχειν</span> e como consequência disso: não ter domínio sobre si mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:20</a> (cf. Eur., Bacch. 291ss.; Hdt. 4, 79 <span class=\"greek\">ὁ</span> <span class=\"greek\">δαίμων</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">βασιλέα</span> <span class=\"greek\">λελάβηκε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μαίνεται</span>; Dio Chrys. 11 [12], 8: a coruja adverte as outras aves acerca dos seres humanos, mas as aves <span class=\"greek\">ἀνόητον</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἡγοῦντο</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαίνεσθαι</span> <span class=\"greek\">ἔφασκον</span>; igualmente Aesop, Fab. 437 P.=105 H.; Diog. L. 1, 49: os membros do conselho ateniense, a respeito de Sólon, <span class=\"greek\">μαίνεσθαι</span> <span class=\"greek\">ἔλεγον</span> <span class=\"greek\">αὐτόν</span>; Orig., C. Cels. 4, 19, 23). Oposto a <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωφροσύνης</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ἀποφθέγγεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:25</a>. <span class=\"greek\">μαίνῃ</span>: estás louca, dirigido a alguém que trouxe uma notícia inacreditável 12:15; estás fora de ti, deliras, dirigido a alguém cujo entusiasmo parece ter ultrapassado o bom senso 26:24 (Ath. 31, 1 e Sallust. 4 p. 6, 8: <span class=\"greek\">μ</span>. como juízo acerca de um homem que proclama determinados ensinamentos; Porphyr., Vi. Plotini c. 15: <span class=\"greek\">μαίνεσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Πορφύριον</span>, avaliação de um poema recitado). Da impressão causada em estranhos pelos que falam em “línguas” <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:23</a> (Herm. Wr. 9, 4: os que estavam cheios da Gnose divina causavam impressão semelhante nos de fora, <span class=\"greek\">μεμηνέναι</span> <span class=\"greek\">δοκοῦσι</span>; cf. Hippol., Ref. 5, 8, 6; Did., Gen. 230, 11).—DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακαρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακαρίζω</span> futuro ático <span class=\"greek\">μακαριῶ</span>; 1º aoristo <span class=\"greek\">ἐμακάρισα</span>; futuro passivo <span class=\"greek\">μακαρισθήσομαι</span> 4 Macc 16:9 (<span class=\"greek\">μάκαρ</span>, “bem-aventurado”; ver os dois verbetes seguintes; Hom. e outros; Vett. Val. 88, 25; LXX; Philo, Exs. 152; Joseph.) chamar ou considerar alguém especialmente favorecido, declarar ou considerar bem-aventurado, feliz, afortunado; <span class=\"greek\">τινά</span>, alguém (Hippocr., Ep. 17; IEph Ia, 11, 17s.; Diod S 13, 58, 2; Chariton 5, 8, 3; Appian, Bell. Civ. 4, 114 §476; Gen 30:13; Sir 11:28; Jos., Bell. 7, 356; <span class=\"greek\">τὸ</span> <span class=\"greek\">μακαρίζεσθαι</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πτωχοὺς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> Orig., C. Cels. 6, 16, 30, com <span class=\"greek\">ἐυφημέω</span> 8, 57, 27; Did., Gen 72, 1; 149, 27) ou <span class=\"greek\">τὶ</span>, alguma coisa (Herodian 5, 1, 5; Jos., C. Ap. 2, 135) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:48</a> (cf. 4Q434 II–III); IEph 5:1; GJs 12:2. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὑπομείναντας</span>, os que mostraram perseverança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:11</a>. <span class=\"greek\">ἑαυτόν</span>, a si mesmo Hs 9, 28, 6; AcPl Ha 6, 7. <span class=\"greek\">τὴν</span> <span class=\"greek\">τελείαν</span> <span class=\"greek\">γνῶσιν</span>, o conhecimento perfeito 1 Cl 1:2. <span class=\"greek\">τὴν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">γνώμην</span>, a atitude dele (do bispo) para com Deus IPhld 1:2. Talvez empregado absolutamente (X., Mem. 1, 6, 9) Dg 10:8.—New Docs 4, 39. DELG s.v. <span class=\"greek\">μάκαρ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακάριος, ία, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακάριος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span> (ver o verbete precedente e o seguinte; Pind., Pla., X. e outros).</p><p class=\"entry-text\">① Relativo a ser afortunado ou feliz em razão das circunstâncias: afortunado, feliz.</p><p class=\"entry-text\">ⓐ De seres humanos, com menor ênfase na dimensão transcendente do que no uso da acepção 2 abaixo (Chrysippus em Diog. L. 7, 179 chama a si próprio <span class=\"greek\">μακάριος</span> <span class=\"greek\">ἀνήρ</span>; Epict. 2, 18, 15; Jos., Ant. 16, 108; 20, 27): <span class=\"greek\">ἥγημαι</span> <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">μακάριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:2</a>. Da viúva que permanece sem contrair novas núpcias: <span class=\"greek\">μακαριωτέρα</span> <span class=\"greek\">ἐστίν</span>, é mais feliz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:40</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἤμην</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">τοιαύτην</span> <span class=\"greek\">γυναῖκα</span> <span class=\"greek\">εἶχον</span> Hv 1, 1, 2 (Chariton 6, 2, 9 <span class=\"greek\">μ</span>. <span class=\"greek\">ἦν</span> <span class=\"greek\">εἰ</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:29</a>.</p><p class=\"entry-text\">ⓑ De seres transcendentes, vistos como privilegiados: bem-aventurado (Aristot., EN 10, 8:1178b, 25s. <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἅπας</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βίος</span> <span class=\"greek\">μακάριος</span>; Epicurus em Diog. L. 10, 123 <span class=\"greek\">τ</span>. <span class=\"greek\">θεὸν</span> <span class=\"greek\">ζῷον</span> <span class=\"greek\">ἄφθαρτον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μακάριον</span> <span class=\"greek\">νομίζων</span>; Herm. Wr. 12, 13b; Sextus 560; Philo, Cher. 86, Deus Imm. 26 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄφθαρτος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μακάριος</span>, Leg. ad Gai. 5 [outras passagens em MDibelius, Hdb./Hermeneia sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:11</a>]; Jos., C. Ap. 2, 190, cf. Ant. 10, 278; cf. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. Hippol., Ref. 5, 9, 21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:11</a>; 6:15 (BEaston, Pastoral Epistles ’47, 179).</p><p class=\"entry-text\">② Relativo a ser especialmente favorecido, bem-aventurado, afortunado, feliz, privilegiado, sob uma perspectiva transcendente, o sentido mais comum (na perspectiva greco-romana geral: aquele a quem a fortuna sorri).</p><p class=\"entry-text\">ⓐ De seres humanos que são destinatários privilegiados do favor divino (Jos., Ant. 9, 264), de personagens bíblicas (<span class=\"greek\">Ἰωβ</span> Did., Gen. 101, 14; cf. <span class=\"greek\">ἄγγελοι</span> Orig., C. Cels. 8, 25, 12): Moisés 1 Cl 43:1; Judite 55:4; profetas AcPlCor 2:36 (Just., D. 48, 4); Paulo (Hippol., Ref. 8, 20, 3; <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπόστολος</span> Iren. 5, 2, 3 [Harv. II 321, 4], referido a Paulo; cf. Orig., C. Cels. 5, 65, 7) 1 Cl 47:1; Pol 3:2 (11:3); AcPl Ha 3, 27. De outros cristãos proeminentes, sobretudo mártires: Inácio, Zósimo, Rufo Pol 9:1; Policarpo MPol 1:1; 19:1, 21; 22:1, 3. De presbíteros falecidos 1 Cl 44:5. <span class=\"greek\">μ</span>. <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ποιήσει</span> <span class=\"greek\">αὐτοῦ</span>, ser bem-aventurado naquilo que se faz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:25</a>.</p><p class=\"entry-text\">Em várias combinações oracionais, nas quais se omite frequentemente a cópula que acompanha <span class=\"greek\">μ</span>. (B-D-F §127, 4; Rob. 395; Maximus Tyr. 14, 6s.; <span class=\"greek\">μ</span>. [oposto a <span class=\"greek\">δυστυχής</span>] <span class=\"greek\">εὐσεβὴς</span> <span class=\"greek\">φίλος</span> <span class=\"greek\">θεοῦ</span>; mas Did., Gen. 103, 2: <span class=\"greek\">μ</span>. <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκκλησία</span>, <span class=\"greek\">ὅτε</span>): como apódose de uma oração condicional <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:4</a> D (Unknown Sayings 49–54); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:14</a>; 4:14; Hm 8:9. A oração condicional aparece depois em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:17</a>; 1 Cl 50:5; Hs 6, 1, 1a. Com oração relativa subsequente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:23</a>; 14:15 (<span class=\"greek\">μ</span>. <span class=\"greek\">ὅστις</span> Menand., Fgm. 101 Kö., Mon. 340 Mei. e outros); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:7</a>s.; 1 Cl 50:6 (ambos Ps 31:1s.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:12</a> (PsSol 6:1; 10:1; Sext. 40 <span class=\"greek\">μ</span>. <span class=\"greek\">ἀνήρ</span> com relativa); 1 Cl 56:6 (Job 5:17); 10:10 (Ps 1:1.—Maximus Tyr. 33, 5e <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀνήρ</span>, <span class=\"greek\">ὅν</span>); 11:8; Hv 2, 2, 7; Hs 9, 29, 3. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστῷ</span>, <span class=\"greek\">ὅς</span> IPhld 10:2. A oração relativa precede em Hv 3, 8, 4; Hs 5, 3, 9b; 6, 1, 1b.</p><p class=\"entry-text\">Como predicativo com substantivo, adjetivo substantivado ou particípio: <span class=\"greek\">μ</span>. <span class=\"greek\">ὁ</span>, bem-aventurado aquele que… (2 Ch 9:7; Da 12:12; PsSol 4:23; ApcEsdr 5:11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:3</a>ss. (a tradução 0, “ó, felicidade dos” ou “salve os”, preferida por alguns [Zahn, Wlh., EKlostermann, JWeiss; KBornhäuser, Die Bergpredigt 1923, 24 e outros], parece corresponder exatamente ao original aramaico [=hebr. <span class=\"hebrew\" dir=\"rtl\">אַשְׁרֵי</span>]; contudo, discute-se entre os estudiosos se ela esgota o conteúdo de <span class=\"greek\">μακάριος</span> na fala dos cristãos de língua grega [ver, por exemplo, Maximus Tyr. 14, 6s. <span class=\"greek\">μακάριος</span> <span class=\"greek\">εὐσεβὴς</span> <span class=\"greek\">φίλος</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">δυστυχὴς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δεισιδαίμων</span>; Artem. 4, 72: a condição de <span class=\"greek\">μ</span>. <span class=\"greek\">εἶναι</span> resulta da ascensão ao céu e da <span class=\"greek\">ὑπερβάλλουσα</span> <span class=\"greek\">εὐδαιμονία</span> ali desfrutada; outras referências em Betz, SM 97–99].—CMcCown, The Beatitudes in the Light of Ancient Ideals: JBL 46, 1927, 50–61; JRezevskis [Resewski], D. Makarismen bei Mt u. Lk, ihr Verhältnis zu einander u. ihr histor. Hintergrund: StThR I [=IBenzinger Festschr.] ’35, 157–70; JDupont, Les Béatitudes ’54; GStrecker, Die Makarismen der Bergpredigt, NTS 17, ’70/71, 255–75; ver bibliografia no verbete <span class=\"greek\">ὄρος</span>); 24:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:45</a>; 6:20ss.; 11:28; 12:37; cf. versículos 38, 43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:3</a>; 14:13; 16:15; 19:9; 20:6; 22:7, 14; 1 Cl 40:4; 48:4; 2 Cl 16:4; 19:3; D 1:5; Pol 2:3 (=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:20</a>; Hv 2, 3, 3). Com <span class=\"greek\">ὅτι</span> depois (JosAs 16:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:14</a>; Hs 2:10; 9, 30, 3. Com <span class=\"greek\">ὅταν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:11</a>. Conforme a leitura do Michigan Pap. (ed. CBonner ’34, p. 46, 11s.) e de uma folha de pergaminho em Hamburgo (SBBerlAk 1909, 1081), Hs 5, 1, 3 contém as palavras <span class=\"greek\">μακάριόν</span> <span class=\"greek\">με</span> <span class=\"greek\">ποιήσεις</span> <span class=\"greek\">ἐάν</span> (assim Whittaker e Joly), tu me farás feliz, se. Com <span class=\"greek\">γίνεσθαι</span> 9, 24, 2.</p><p class=\"entry-text\">ⓑ De coisas ou experiências: bem-aventurado (Eur. e posteriores; Eccl 10:17).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. De partes do corpo de pessoas que são objeto de graça especial, consideradas elas próprias bem-aventuradas: <span class=\"greek\">μ</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀφθαλμοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:23</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">κοιλία</span> 11:27 (Cleopatra linhas 168s.; provavelmente cristã, apesar da referência a Cleop. Entre os paralelos em escritos não bíblicos, o mais próximo é Musaeus, Hero 137 … <span class=\"greek\">γαστήρ</span>, <span class=\"greek\">ἥ</span> <span class=\"greek\">σ</span>’ <span class=\"greek\">ἐλόχευσε</span> <span class=\"greek\">μακαρτάτη</span>).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. De coisas que mantêm relação muito estreita com a divindade: <span class=\"greek\">τὰ</span> <span class=\"greek\">δῶρα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> 1 Cl 35:1. Dos <span class=\"greek\">πνεύματα</span> implantados nos cristãos 1:2 (cf. Maximus Tyr. 41, 51: a <span class=\"greek\">εὐδαίμων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μακαρία</span> <span class=\"greek\">ψυχή</span>). Da era vindoura 2 Cl 19:4 (cf. OGI 519, 9 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μακαριοτάτοις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">καιροῖς</span>; 17).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Dos martírios MPol 2:1. Do objeto da esperança cristã: <span class=\"greek\">προσδεχόμενοι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐλπίδα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:13</a> (cf. OGI 383, 108 <span class=\"greek\">μακαριστὰς</span> <span class=\"greek\">ἐλπίδας</span>). <span class=\"greek\">μακάριόν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">λαμβάνειν</span>, é mais bem-aventurado dar do que receber <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:35</a> (cf. Pla., Rep. 496c <span class=\"greek\">ὡς</span> <span class=\"greek\">μακάριον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κτῆμα</span>; 1 Cl 2:1; Beginn. IV 264; Unknown Sayings, 78–81; EHaenchen, Ac ad loc. Sobre Thu. 2, 97, 4 <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">διδόναι</span>, ver JKilgallen, JBL 112, ’93, 312–14.).—HSanders, HTR 36, ’43, 165–67. Ver bibliografia no verbete <span class=\"greek\">ὄρος</span> e cf. <span class=\"greek\">εὐδαιμονέω</span>.—B. 1105. DELG s.v. <span class=\"greek\">μάκαρ</span>. Schmidt, Syn. IV 402–6. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακαρισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακαρισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (ver os dois verbetes precedentes; Pla., Rep. 9, 591d; Aristot., Rhet. 1, 9, 34 [1367b, 25–36]; Plut., Sol. 27, 7, Mor. 471c; Stob., Ecl. III 57, 14 H.; Philo, Somn. 2, 35; Jos., Bell. 6, 213; SibOr 13, 117; Orig., C. Cels. 2, 64, 16; Did., Gen. 26, 19s.) declaração de que se recebe favor especial, pronunciamento de bem-aventurança, bênção, a propósito de uma citação dos Salmos que começa por <span class=\"hebrew\" dir=\"rtl\">אַשְׁרֵי</span>=<span class=\"greek\">μακάριος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:6</a>, 9; 1 Cl 50:7 (ambos Ps 31:1s.). <span class=\"greek\">ποῦ</span> <span class=\"greek\">οὗν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὑμῶν</span>; onde está, pois, a vossa bem-aventurança? isto é, a disposição de espírito em que vos consideráveis bem-aventurados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:15</a> (cf. Betz, Gal. 226s.).—GDirichlet, De veterum macarismis 1914; CClassen, WienerStud 107/108, ’94/95, 328s. Ver também <span class=\"greek\">εὐλογέω</span>, final.—DELG s.v. <span class=\"greek\">μάκαρ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μακεδονία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μακεδονία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hdt. e outros; inscrições [especialmente IMakedD], Philo, Joseph., SibOr [-<span class=\"greek\">ίη</span>]) Macedônia, província romana desde 146 a.C., província senatorial no tempo de Paulo. Visitada diversas vezes por Paulo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:9</a>s., 12; 18:5; 19:21s.; 20:1, 3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:13</a>; 7:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:7</a>s.; 4:10; AcPl Ha 5, 16; 27. Plano de viagem relativo à Macedônia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:5a</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:16a</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:3</a>. Apoio dado a Paulo pela congregação macedônia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:9</a>. Também participaram ativamente da coleta para Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:1</a>.—Pauly-W. XIV 638ss.; Kl. Pauly III 910ss.; BHHW II 1178s.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μακεδών, όνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μακεδών</span>, <span class=\"greek\">όνος</span>, <span class=\"greek\">ὁ</span> (Hdt. e outros; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 18, 1; Arrian: 156 Fgm. 9, 17 Jac.; Polyaenus 1, prooem., 1 [nos três casos M. <span class=\"greek\">ἀνήρ</span>]; inscrições, papiros; Esth 8:12k; Philo, Omn. Prob. Lib. 94; Joseph., SibOr) macedônio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:9</a> (AWikenhauser, Religionsgesch. Parallelen zu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:9</a>; BZ 23, ’35, 180–86). Referente a Gaio e Aristarco 19:29. A Aristarco 27:2. No plural, dos cristãos macedônios ou seus representantes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:2</a>, 4.—Haenchen ad loc.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάκελλον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάκελλον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (não era originalmente uma palavra latina incorporada ao grego [como em Rob. 109], pois é atestada em grego desde cerca de 400 a.C. numa inscrição de Epidauro [GDI III/1, 3325=IG IV2/1, 102, 107; 296; 298; 301], na forma <span class=\"greek\">μάκελλον</span> com o sentido de “recinto, gradeamento”. O sentido “mercado de carne” é encontrado para o latim macellum em Plauto e Terêncio e posteriores [séculos III/II a.C.]; o exemplo grego mais antigo de <span class=\"greek\">μ</span>. nesse sentido é SIG 783 [IG V/2, 268], 45 [século I a.C.], em que é masculino, <span class=\"greek\">μάκελλος</span>, assim como no escólio a Aristoph., Eq. 137; Vi. Aesopi G 51 P.; cf. macellus em Marcial e as versões saídica e boárica de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:25</a>. Ver Cadbury abaixo, 134 n. 2. Em outros lugares, a palavra é neutra [também assim na Peshîttâ e no siríaco harclense] ou seu gênero não pode ser determinado. É possível que <span class=\"greek\">μ</span>. tenha reentrado no grego helenístico com esse novo sentido; assim Hahn 249 n. 6. Quanto à hipótese de <span class=\"greek\">μ</span>. ser de origem semítica [AWalde, IndogF 39, 1921, 82; B-D-F §5, 1, apêndice], embora de natureza dórico-jônica segundo Varro, De Lingua Lat. 5, 146 Goetz-Schoell, ver JSchneider, TW IV 373s.—Plut., Mor. 277d; Cass. Dio 61, 18, 3 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀγορὰν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀψῶν</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">μάκελλον</span>; Vita Aesopi G 51 <span class=\"greek\">ὁ</span> <span class=\"greek\">μάκελλος</span>, onde se vende carne de porco; IG V/1, 149; 150; SIG 783, 45 [<span class=\"greek\">μάκελλος</span>]; BCH 17, 1893, 261; 20, 1896, 126; PHerm127 [3] verso, 5) mercado de carne, mercado de alimentos (ver planta de um em Pompeia em AMau, Pompeji2 1908, 90–97, reproduzida a partir dali em Ltzm., Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:25</a>. Também HCadbury, The Macellum of Corinth: JBL 53, ’34, 134–41, com inscrição latina encontrada em Corinto contendo a palavra “macellum”: Corinth, Results of Excavations VIII/2, ’31, n.os 124; 125). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">πωλούμενον</span> <span class=\"greek\">ἐσθίειν</span>, comer o que se vende no mercado de carne <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:25</a>.—B. 365. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακράν</h1><div class=\"entry-meta\"><span>advérbio e preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακράν</span> (forma feminina fixa, originalmente um acusativo de extensão espacial, subentendendo-se <span class=\"greek\">ὁδόν</span>.—Aeschyl. e outros; também papiros, LXX, En; TestSim 6:2; TestNaphth 4:5; GrBar 4:16; Philo, Joseph., Tat.).</p><p class=\"entry-text\">① Relativo a estar a uma distância relativamente grande de certa posição: longe, distante.</p><p class=\"entry-text\">ⓐ Como advérbio de lugar.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Referente à extensão espacial (Sir 24:32): <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπέχειν</span>, estar longe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:20</a> (PCairZen 605, 3 <span class=\"greek\">οὐ</span> <span class=\"greek\">μακράν</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἀπέχομεν</span>). <span class=\"greek\">εἰς</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">μακρὰν</span> <span class=\"greek\">ἐξαποστελῶ</span> <span class=\"greek\">σε</span>, eu te enviarei para longe, às nações gentílicas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:21</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (Polyb. 3, 45, 2; LXX; Jos., C. Ap. 1, 60; SibOr 8, 33s.): <span class=\"greek\">ῥίπτειν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span>, lançar para longe da torre Hv 3, 2, 7 e 9; 3, 6, 1; 3, 7, 1; Hs 9, 7, 2; cf. <span class=\"greek\">μακρὰν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀπερίφησαν</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span> v 3, 5, 5. <span class=\"greek\">μ</span>. <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, estar longe de alguém ou alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:8</a>; Hs 1:1 (ver <span class=\"greek\">β</span> abaixo). <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπέχειν</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (Pr 15:29; 1 Macc 8:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:6</a>; MPol 5:1. A respeito de Deus, <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">ἑκάστου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ὑπάρχοντα</span>, não estando longe de cada um de nós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:27</a> (cf. Dio Chrys. 11 [12], 28 <span class=\"greek\">οὐ</span> <span class=\"greek\">μακρὰν</span> <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ἔξω</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θείου</span> … , <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μέσῳ</span> [ver <span class=\"greek\">σύμφυτος</span>]; Jos., Ant. 8, 108). O sentido espacial, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:21</a>, provavelmente é expresso por <span class=\"greek\">τοῖς</span> <span class=\"greek\">τέκνοις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., a vossos filhos e a todos os que estão longe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:39</a> (cf. REB; NRSV), mas ver 2 abaixo.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Sentido transferido (Epict. 3, 22, 11 <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτοῦ</span>=longe de um verdadeiro cínico): <span class=\"greek\">μ</span>. <span class=\"greek\">ὄντες</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> Hm 12, 4, 4. <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">εἶ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, não estás longe do reino de Deus, isto é, estás quase pronto para nele entrar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:34</a> (cf. Ps 21:2 <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">μου</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">μακράν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">ταύτης</span> Hs 1:1 (ver <span class=\"greek\">α</span> acima; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:14</a>). <span class=\"greek\">οἱ</span> <span class=\"greek\">μ</span>. (oposto a <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐγγύς</span>; cf. Is 57:19; Da 9:7 Theod.; Esth 9:20), os que estão longe, acerca dos gentios (em contraposição aos israelitas, cf. v. 12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:17</a>. <span class=\"greek\">οἵ</span> <span class=\"greek\">ποτε</span> <span class=\"greek\">ὄντες</span> <span class=\"greek\">μ</span>., vós que outrora estáveis longe, v. 13. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιθυμία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πονηρά</span> … <span class=\"greek\">φεύξεται</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">σου</span> <span class=\"greek\">μ</span>., o desejo mau fugirá para longe de ti Hm 12, 2, 4.</p><p class=\"entry-text\">ⓑ Empregado como preposição: <span class=\"greek\">μ</span>. <span class=\"greek\">τινος</span>, longe de alguém ou de alguma coisa (Herodas 7, 111 <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἐκεῖνος</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μακρὴν</span> <span class=\"greek\">ἀπῴκισται</span>; Polyb. 3, 50, 8; Polyaenus 5, 2, 10; GrBar 4:16 <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">μ</span>. <span class=\"greek\">γίνονται</span>; Just., D. 3, 1 <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θαλάσσης</span>; Tat. 12, 4 <span class=\"greek\">μ</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐταξίας</span>; PCairZen 605, 3 [ver o início de 1ⓐ<span class=\"greek\">α</span> acima]; POxy 113, 18; Sir 15:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:6</a>, variante textual. <span class=\"greek\">μ</span>. <span class=\"greek\">πάσης</span> <span class=\"greek\">ἁμαρτίας</span> Pol 3:3; cf. 4:3; 6:1. <span class=\"greek\">ὧν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">πραΰτης</span> D 5:2. <span class=\"greek\">ὧν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">πόρρω</span> <span class=\"greek\">πραΰτης</span> 20:2.</p><p class=\"entry-text\">② Relativo a uma posição temporal relativamente distante do presente: no futuro, em tempo vindouro. <span class=\"greek\">τοῖς</span> <span class=\"greek\">τέκνοις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:39</a> (cf. 2 Km 7:19 <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>.=v. 16 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span>; Sir 24:32 <span class=\"greek\">ἐκφανῶ</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>.—<span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. também em Demosth. 18, 36; Polyaenus 6, 7, 1; Jos., Ant. 6, 278; 20, 153; TestSim 6:2; Just., D. 2, 5; PMeyer 66, 2 [óstraco]), mas ver 1ⓐ<span class=\"greek\">α</span> acima.—DELG s.v. <span class=\"greek\">μακρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρόβιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακρόβιος</span>, <span class=\"greek\">ον</span> (ver <span class=\"greek\">μακρός</span>, <span class=\"greek\">βίος</span>; Hippocr. e posteriores; LXX; Philo; Jos., Bell. 2, 151) de vida longa, longevo. <span class=\"greek\">σπέρμα</span> <span class=\"greek\">μ</span>., descendência longeva 1 Cl 16:11 (segundo Is 53:10).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρόθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακρόθεν</span>, advérbio de <span class=\"greek\">μακρός</span> (grego helenístico: Chrysippus em Athen. 4, 137s.; Polyb. 29, 8, 4; Strabo 3, 3, 4; Epict. 1, 16, 11; Dio Chrys. 1, 68 e outros; Aelian, NA 2, 15; 15, 12; PTebt 230 [século II a.C.]; LXX; En 32:3; PsSol 11:3; TestJob 28:3; JosAs 24:17; ParJer 8:11; Philo; ver Phryn. 93 Lob.): de longe, a distância (Ezk 23:40 <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">μ</span>.; Tob 13:13). <span class=\"greek\">μ</span>. <span class=\"greek\">ἀκολουθεῖν</span>, seguir a distância <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:58</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:54</a>. <span class=\"greek\">ἑστὼς</span> <span class=\"greek\">μ</span>., permaneceu a certa distância 18:13 (coleção de fábulas de Esopo de Syntipas 37 p. 541 P. <span class=\"greek\">μ</span>. <span class=\"greek\">ἑστῶσα</span>).—Mais frequentemente <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μ</span>. (Ps.-Polemo Physiogn. 15 p. 319, 9 F.; Ps 137:6; 2 Esdr 3:13), pois o sufixo -<span class=\"greek\">θεν</span> perdeu sua força separativa original (B-D-F §104, 3; Rob. 300; KDieterich, Untersuchungen z. Geschichte d. griech. Sprache 1898, 183s.—Cf. <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐρανόθεν</span>: Eratosthenes [século III a.C.] 16, 11 Coll.; PGM 2, 83; SibOr 3, 691.—<span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μικρόθεν</span>: POxy 1216, 6 [séculos II/III d.C.]). <span class=\"greek\">ἀκολουθεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μ</span>., seguir a distância <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:58</a> (a leitura varia; a variante omite <span class=\"greek\">ἀπό</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:54</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θεωρεῖν</span>, observar a distância <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:40</a>. <span class=\"greek\">ὁρᾶν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μ</span>. 5:6; 11:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:23</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἑστηκέναι</span>, ficar a distância (Ps 37:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:49</a> (quanto a toda a situação, bem como aos detalhes da expressão, cf. Appian, Bell. Civ. 2, 85 §360 <span class=\"greek\">τὸ</span> <span class=\"greek\">γύναιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Πομπηίου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">φίλοι</span> <span class=\"greek\">ταῦτα</span> [isto é, o assassinato de Pompeu] <span class=\"greek\">μακρόθεν</span> <span class=\"greek\">ὁρῶντες</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:10</a>, 15, 17. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἥκειν</span>, viver longe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:3</a> (FDanker, JBL 82, ’63, 215; BvanIersel, NovT 7, ’64, 184s.).—DELG s.v. <span class=\"greek\">μακρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροθυμέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακροθυμέω</span> (ver <span class=\"greek\">μακρόθυμος</span>), 1º aoristo <span class=\"greek\">ἐμακροθύμησα</span>.</p><p class=\"entry-text\">① Permanecer tranquilo enquanto se espera: ter paciência, esperar (Plut., Mor. 59s.; Job 7:16; Sir 2:4; Bar 4:25; TestJob 22:5 e outros; TestJos 2:7), em emprego absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:8</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, esperar pacientemente alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7b</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἕως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">παρουσίας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίου</span>, ter paciência até a vinda do Senhor v. 7a.</p><p class=\"entry-text\">② Suportar a provocação sem se queixar: ser paciente, longânimo (LXX; ApcEsdr 3:6 p. 27, 11 Tdf.), em emprego absoluto (Pr 19:11), referido a Deus (Iren. 1, 10, 3 [Harv. I 95, 5]; Hippol., Ref. 1 pref.) Dg 9:2. Do amor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:4</a>. <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">μακροθυμεῖ</span>, o amor é paciente em todas as coisas 1 Cl 49:5. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, para com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:14</a>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, com alguém IPol 6:2. <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, para com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:9</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, com alguém (Sir 18:11; 29:8; cf. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἡμᾶς</span> TestJob 11:10; <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span> ApcEsdr 3:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:26</a>, 29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:7</a> (ver FDanker, Jesus and the New Age, ’88, comentário ao lugar sobre a sequência do pensamento; para uma interpretação alternativa, ver 3 abaixo).</p><p class=\"entry-text\">③ Demorar, retardar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:7</a>: <span class=\"greek\">μακροθυμεῖ</span> (texto incerto [variante -<span class=\"greek\">θυμών</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοῖς</span>] e interpretação difícil, mas cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:12</a> quanto à mistura de tempos numa pergunta) pode ser traduzido: “Deus demorará muito em socorrê-los?” (NRSV; ver Weizsäcker3–8; Fitzmyer, Luke, comentário ao lugar, com ênfase em Sir 35:19; <span class=\"greek\">μ</span>.=demorar: Artem. 4, 11).—Jülicher, Gleichn. 286ss.; HSahlin, Zwei Lk-Stellen: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:43</a>–45; 18:7: SymbBUps 4, ’45, 9–20; HRiesenfeld, NT Aufsätze (JSchmid Festschr.), ’63, 214–17 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:7</a>); mas ver KBeyer, Semit. Syntax im NT, ’62, 268 n. 1.—DELG s.v. <span class=\"greek\">θυμός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροθυμία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακροθυμία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ver os dois verbetes seguintes; Menand.; Strabo 5, 4, 10; Comp. I, 282ss.; LXX; TestJob, Test12Patr; SyrBar 12:4 [?]; ApcEsdr 2:8 p. 25, 30 Tdf.).</p><p class=\"entry-text\">① Estado de permanecer tranquilo enquanto se aguarda um resultado: paciência, firmeza, perseverança (Menand., Fgm. 19; Plut., Lucull. 514 [32, 3; 33, 1]; Comp. I, 282ss.; Is 57:15; PLond VI, 1917, 5 [século IV d.C.]; 1 Macc 8:4; TestJob 27:7; TestDan 2:1; Jos., Bell. 6, 37; Orig., C. Cels. 2, 34, 41 [com <span class=\"greek\">ἀνεξικακία</span>]), com <span class=\"greek\">ὑπομονή</span> (TestJos 2:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:11</a>; 1 Cl 64; IEph 3:1; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:10</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μακροθυμίας</span>, mediante fé e perseverança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:12</a>. <span class=\"greek\">ὑπόδειγμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κακοπαθίας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">μακροθυμίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:10</a>. Com <span class=\"greek\">ταπεινοφροσύνη</span> Hs 8, 7, 6; cf. 9, 15, 2.</p><p class=\"entry-text\">② Estado de ser capaz de suportar a provocação: longanimidade, paciência para com os outros (Artem. 2, 25 p. 119, 10).</p><p class=\"entry-text\">ⓐ Referido a seres humanos (Pr 25:15; Sir 5:11; TestJos 17:2), em associação com outras virtudes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:22</a>; 1 Cl 62:2. Com <span class=\"greek\">ἐπιείκεια</span> (cf. EpArist 188) 1 Cl 13:1. Com <span class=\"greek\">πραΰτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:12</a>. Com <span class=\"greek\">ἐγκράτεια</span> 2:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">μακροθυμίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:2</a>. Em contraste com <span class=\"greek\">ὀξυχολία</span>: Hm 5, 1, 3 e 6; 5, 2, 3 e 8. <span class=\"greek\">μετὰ</span> <span class=\"greek\">μακροθυμίας</span> <span class=\"greek\">ἀνεχόμενοι</span> <span class=\"greek\">ἀλλήλων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:2</a>.</p><p class=\"entry-text\">ⓑ Referido a seres transcendentes:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. A Deus (ApcEsdr 2:8; Did., Gen. 186, 10 [restituído]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:4</a>; 9:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:20</a>; IEph 11:1.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. A Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:15</a>.—Ver <span class=\"greek\">ὑπομονή</span> 1, final.—DELG s.v. <span class=\"greek\">θυμός</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρόθυμος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακρόθυμος</span>, <span class=\"greek\">ον</span> (ver os dois verbetes precedentes e o seguinte; M. Ant. 6, 30, 10; Anth. Pal. 11, 317, 1; LXX; TestJob 21:4; TestDan 6:9; JosAs 11 cód. A [p. 54, 7 Bat.] e Pal 364) relativo ao domínio de si diante de provocação: paciente, longânimo, tolerante, equilibrado.</p><p class=\"entry-text\">ⓐ De seres humanos (Pr 14:29; 15:18; 16:32 e outros) Hv 1, 2, 3; m 5, 1, 1; cf. 2; D 3:8. <span class=\"greek\">μακρόθυμον</span> <span class=\"greek\">εἶναι</span> Hm 8:10.</p><p class=\"entry-text\">ⓑ De Deus (PLond VI 1917, 25 [século IV d.C., cristão]; Ex 34:6; Num 14:18; 2 Esdr 19:17 e outros) Hs 8, 11, 1. Com <span class=\"greek\">φιλάνθρωπος</span> Dg 8:7; <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>., aquele que é paciente, isto é, Deus 3:6. <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">βούλημα</span> 1 Cl 19:3.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροθύμως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακροθύμως</span> (advérbio de <span class=\"greek\">μακρόθυμος</span>), pacientemente. <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">τινός</span>, ouvir alguém com paciência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:3</a>.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (Hom. e posteriores; palavra emprestada no rabínico).</p><p class=\"entry-text\">① Relativo a consumir um tempo relativamente longo: longo, demorado; o neutro usado como advérbio (esse emprego do neutro pode referir-se tanto ao espaço como ao tempo: desde Hom.; de espaço, por exemplo, Il. 2, 224 <span class=\"greek\">μακρὰ</span> <span class=\"greek\">βοᾶν</span>=gritar para ser ouvido a grande distância; TestJob 31:2 <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μακρά</span> <span class=\"greek\">μου</span> <span class=\"greek\">ὄντες</span> [funcionando como preposição]; de tempo, ViZech 6 <span class=\"greek\">ἐν</span> <span class=\"greek\">γήρει</span> <span class=\"greek\">μακρῷ</span>; Jos.Jos., Ant. 6, 241): <span class=\"greek\">μακρὰ</span> <span class=\"greek\">προσεύχεσθαι</span>, fazer longas orações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:13</a> [14], variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:47</a>.</p><p class=\"entry-text\">② Relativo a estar relativamente afastado: longínquo, distante (Aeschyl., Prom. 814 <span class=\"greek\">μ</span>. <span class=\"greek\">ἀποικία</span>; Mi 4:3=ViHab 6 [p. 86, 8 Schermann] <span class=\"greek\">εἰς</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">μακράν</span>): <span class=\"greek\">εἰς</span> <span class=\"greek\">χώραν</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:13</a>; 19:12.—B. 882. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μακροχρόνιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μακροχρόνιος</span>, <span class=\"greek\">ον</span> (ver <span class=\"greek\">μακρός</span>, <span class=\"greek\">χρόνος</span>; Hippocr. e posteriores; Philo, Rer. Div. Her. 34; TestSol PVindobBosw 18, 34) de vida longa, longevo (Porphyr., Vi. Pyth. 24 N.). <span class=\"greek\">ἵνα</span> … <span class=\"greek\">ἔσῃ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, para que tenhas longa vida sobre a terra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:3</a> (Ex 20:12; Dt 5:16; cf. CPR V, 19, 5 <span class=\"greek\">ἰς</span> <span class=\"greek\">μακροὺς</span> <span class=\"greek\">χρόνους</span>, “por muitos anos vindouros”).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλα</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάλα</span>, “muito, extremamente”; ver a forma comparativa <span class=\"greek\">μᾶλλον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαλακία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ver os dois verbetes seguintes; com diversos sentidos: “maciez, fraqueza, debilidade, enfermidade” Hdt. e outros; papiros, LXX, Philo; Jos., Ant. 4, 169; 17, 109; TestJos 17:7; palavra emprestada no rabínico).</p><p class=\"entry-text\">① Condição de fraqueza corporal: debilidade, fraqueza, enfermidade (Menand., Fgm. 177, 5 Kö.; Vit. Hom. 36; Dt 7:15; 28:61; Is 38:9), com <span class=\"greek\">νόσος</span> (como nos amuletos cristãos, que evidentemente dependem da linguagem do NT: POxy 1151, 27; BGU 954, 12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:23</a>; 9:35; 10:1. <span class=\"greek\">εἰδὼς</span> <span class=\"greek\">φέρειν</span> <span class=\"greek\">μαλακίαν</span>, aquele que sabe suportar a fraqueza 1 Cl 16:3 (Is 53:3).</p><p class=\"entry-text\">② Condição de fraqueza interior: pusilanimidade, desânimo, falta de energia (Thu. 1, 122, 4; Demosth. 11, 22); no plural (com <span class=\"greek\">διψυχία</span>) Hv 3, 11, 2; 3, 12, 3.—DELG s.v. <span class=\"greek\">μαλακός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακίζομαι</h1><div class=\"entry-meta\"><span>verbo médio-passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαλακίζομαι</span> (ver <span class=\"greek\">μαλακός</span>) perfeito médio-passivo, 3ª pessoa do singular, <span class=\"greek\">μεμαλάκισται</span>; 1º aoristo passivo <span class=\"greek\">ἐμαλακίσθην</span> (geralmente com conotação negativa: “ser amolecido, ser efeminado, mostrar covardia”, Thu. e posteriores; SIG2 850, 24; PSI 420, 16 [século III a.C.]; PPetr II, 19, 2, 6 [século III a.C.]; Sb 158; LXX, Test12Patr; JosAs 29:9; Philo; Jos., Bell. 4, 43, Ant. 6, 365; 18, 205) estar numa condição de fraqueza, ser ou tornar-se fraco, desanimado, enfermo. <span class=\"greek\">μαλακισθέντες</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βιωτικῶν</span> <span class=\"greek\">πραγμάτων</span>, enfraquecidos pelas obrigações da vida cotidiana Hv 3, 11, 3 (<span class=\"greek\">μαλακίζεσθαι</span> <span class=\"greek\">ἀπό</span>, como em TestGad 1:4, variante textual).—<span class=\"greek\">μεμαλάκισται</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀνομίας</span> <span class=\"greek\">ἡμῶν</span>, foi levado a sofrer por nossas iniquidades 1 Cl 16:5; cf. 5:2 (ambos Is 53:5).—DELG s.v. <span class=\"greek\">μαλακός</span>. M-M. s.v. <span class=\"greek\">μαλακία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0224-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλακός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαλακός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (ver os dois verbetes precedentes; “macio”: Hom. e outros; inscrições, papiros, LXX, Philo; Jos., Ant. 8, 72 <span class=\"greek\">βύσσος</span> <span class=\"greek\">μ</span>.; Mel., P. 80, 594 <span class=\"greek\">στρωμνῆς</span> <span class=\"greek\">μ</span>.).</p><p class=\"entry-text\">① Relativo a ceder ao toque: macio, suave, a respeito de coisas, particularmente roupas (Hom. e outros; Artem. 1, 78 p. 73, 10 <span class=\"greek\">ἱματίων</span> <span class=\"greek\">πολυτελῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μαλακῶν</span>; PSI 364, 5 <span class=\"greek\">ἱμάτιον</span> <span class=\"greek\">μαλ</span>.). <span class=\"greek\">μ</span>. <span class=\"greek\">ἱμάτια</span>, vestes macias, como as usadas por pessoas requintadas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:25</a>. (<span class=\"greek\">τὰ</span>) <span class=\"greek\">μ</span>., vestes macias (Sb 6779, 57; ver <span class=\"greek\">λευκός</span> 2, final) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:8a</a>b.</p><p class=\"entry-text\">② Relativo ao papel passivo em relação sexual entre pessoas do mesmo sexo: efeminado, especialmente de rapazes e homens que se submetem à penetração sexual por outros homens numa relação desse tipo; oposto a <span class=\"greek\">ἀρσενοκοίτης</span> (Dionys. Hal. 7, 2, 4; Dio Chrys. 49 [66], 25; Ptolem., Apotel. 3, 15, 10; Vett. Val. 113, 22; Diog. L. 7, 173; PHib 54, 11 [cerca de 245 a.C.] talvez tenha este sentido: um músico chamado Zenóbio, <span class=\"greek\">ὁ</span> <span class=\"greek\">μαλακός</span> [provavelmente com atividade paralela, segundo Dssm., LO 131, 4—LAE 164, 4]. Ver também inscrição macedônia em LDuchesne e CBayet, Mémoire sur une Mission au Mont Athos 1876 n.º 66 p. 46; Plautus, Miles 668 cinaedus [grego <span class=\"greek\">κίναιδος</span>] malacus; cf. a crítica à moralidade do homoerotismo receptivo em Aeschin. 1, 188; DCohen, Greece and Rome 23, ’76, 181s.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:9</a> (=Pol 5:3). A tradução “prostitutos masculinos” da NRSV é excessivamente restrita; “pervertido sexual” da REB é excessivamente ampla.—Ver bibliografia no verbete <span class=\"greek\">ἀρσενοκοίτης</span>. B. 1065. DELG. M-M.</p></section></article>"};
